/* ---------- Proposal card ---------- */
/* a suggestion posted in the chat: no container; with .panel it becomes a card, its content 16px from every edge */
.dm-prx{padding:var(--dm-s-4) 0;display:flex;flex-direction:column;gap:var(--dm-s-3);container-type:inline-size}
.dm-prx.dm-panel{padding:var(--dm-s-4)}
.dm-prx-h{display:flex;gap:10px;align-items:center}
.dm-prx-ic{width:32px;height:32px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-pp-bg);color:var(--dm-pp);display:grid;place-items:center;flex:none}
.dm-prx-ht{display:flex;flex-direction:column;min-width:0}
.dm-prx-ht b{font-weight:500;font-size:13.5px}
.dm-prx-ht span{font-size:12.5px}
.dm-prx-diff{display:flex;align-items:center;gap:var(--dm-s-2);padding:10px;border-radius:var(--dm-r-in);background:var(--dm-chip);flex-wrap:wrap}
.dm-prx-sw{display:flex;align-items:center;gap:var(--dm-s-2);font-size:12px;flex:1;min-width:0}
.dm-prx-ar{color:var(--dm-muted);display:grid}
/* too narrow for the change on one line (a phone): the new value goes under the old one, the arrow pointing down between
   them under the swatches, so nothing runs out of the box */
@container (max-width:300px){.dm-prx-diff{flex-direction:column;align-items:flex-start;gap:6px}.dm-prx-sw{flex:none}.dm-prx-ar{width:18px;justify-items:center;transform:rotate(90deg)}}
.dm-prx-c{width:18px;height:18px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));flex:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.08);transition:background .5s var(--dm-ease)}
.dm-prx-new .dm-num{transition:opacity .3s}
.dm-prx-cf{display:flex;align-items:center;gap:10px;font-size:12.5px}
.dm-prx-seg{display:flex;gap:3px;flex:1}
.dm-prx-seg i{flex:1;height:5px;border-radius:var(--dm-r-tiny,3px);background:var(--dm-line);transition:background .4s}
/* the confidence is a meter, so its parts take the bright mark green (3:1), not the darker text green */
.dm-prx-seg i.dm-on{background:var(--dm-ok-mark)}
.dm-prx-pc{width:34px;text-align:right;color:var(--dm-fg2)}
/* the toggle's chevron sits on the content's edge, its hover box reaching out round it */
.dm-prx-alt-t{display:flex;align-items:center;gap:6px;margin:-4px -8px;padding:4px 8px;border-radius:var(--dm-r-pill);font-size:12.5px;color:var(--dm-fg2);align-self:flex-start;transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-prx-alt-t:hover{background:color-mix(in srgb,var(--dm-fg) 5%,transparent);color:var(--dm-fg)}}
.dm-prx-alt-t svg{transition:transform .4s var(--dm-ease)}
.dm-prx-alt-t.dm-open svg{transform:rotate(90deg)}
/* the other options: each row's fill is the content's width, no wider, and its swatch and value sit on the columns of the
   change above (10px and 36px in) */
.dm-prx-alts{display:flex;flex-direction:column;gap:2px;padding-top:var(--dm-s-1)}
.dm-prx-a{display:flex;align-items:center;gap:var(--dm-s-2);padding:7px 10px;border-radius:var(--dm-r-in);font-size:13px;text-align:left;transition:background-color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.dm-prx-a:hover{background:var(--dm-row)}}
.dm-prx-a .dm-d{margin-left:auto;font-size:12px;color:var(--dm-muted)}
/* narrow (a phone): each other option's line goes under its name, the swatch centred beside the two */
@container (max-width:300px){.dm-prx-a{display:grid;grid-template-columns:18px minmax(0,1fr);column-gap:var(--dm-s-2)}.dm-prx-a .dm-prx-c{grid-row:1/3;align-self:center}.dm-prx-a .dm-d{grid-column:2;margin-left:0}}
/* the footer sits under a hairline in Soft and Blueprint (owner, 21 Nov), 12px from it on each side; Clean's is a foot strip */
.dm-prx-f{display:flex;align-items:center;justify-content:flex-end;gap:6px;padding-top:var(--dm-s-3);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.dm-prx .dm-pill:active{transform:none}
/* accepted: a neutral line with the green tick (owner, 18 Nov), and Undo */
.dm-prx-done{display:flex;align-items:center;gap:var(--dm-s-2);min-width:0;font-size:13px;color:var(--dm-fg);flex:1}
.dm-prx-done>svg{flex:none;color:var(--dm-ok-mark)}
/* Clean (owner, 19 Nov): a round card with its content 16px from every edge and an off-white foot strip, 16px under the
   options, whose buttons sit 8px from the card's edges, round in its 22px corners; once you answer, the strip holds what
   happened (its words 16px in) and Undo. The head's tile is the neutral one with a hairline, as every Clean tile */
:root[data-style="clean"] .dm-prx.dm-panel,:root [data-style="clean"] .dm-prx.dm-panel,:root [data-style="clean"].dm-prx.dm-panel{padding:16px 16px 0}
:root[data-style="clean"] .dm-prx-ic,:root [data-style="clean"] .dm-prx-ic,:root [data-style="clean"].dm-prx-ic{background:var(--dm-chip);color:var(--dm-fg2);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .dm-prx-ht b,:root [data-style="clean"] .dm-prx-ht b,:root [data-style="clean"].dm-prx-ht b{line-height:20px}
:root[data-style="clean"] .dm-prx-ht span,:root [data-style="clean"] .dm-prx-ht span,:root [data-style="clean"].dm-prx-ht span{line-height:18px}
:root[data-style="clean"] .dm-prx-seg i,:root [data-style="clean"] .dm-prx-seg i,:root [data-style="clean"].dm-prx-seg i{transition:background-color var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .dm-prx-alt-t svg,:root [data-style="clean"] .dm-prx-alt-t svg,:root [data-style="clean"].dm-prx-alt-t svg{transition:transform var(--dm-t) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-prx-alt-t:hover,:root [data-style="clean"] .dm-prx-alt-t:hover,:root [data-style="clean"].dm-prx-alt-t:hover,:root[data-style="clean"] .dm-prx-a:hover,:root [data-style="clean"] .dm-prx-a:hover,:root [data-style="clean"].dm-prx-a:hover{background:var(--dm-row)}}
:root[data-style="clean"] .dm-prx.dm-panel .dm-prx-f,:root [data-style="clean"] .dm-prx.dm-panel .dm-prx-f,:root [data-style="clean"].dm-prx.dm-panel .dm-prx-f{margin:4px -16px 0;padding:8px 16px;gap:4px;min-height:45px;border-top:1px solid var(--dm-line);background:var(--dm-strip);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .dm-prx.dm-panel .dm-prx-done,:root [data-style="clean"] .dm-prx.dm-panel .dm-prx-done,:root [data-style="clean"].dm-prx.dm-panel .dm-prx-done{padding-left:8px}
/* (a step of --dm-ok in the vivid green keeps the tick at 3:1 on the off-white strip, as Attachment tray's does) */
:root[data-style="clean"] .dm-prx.dm-panel .dm-prx-done>svg,:root [data-style="clean"] .dm-prx.dm-panel .dm-prx-done>svg,:root [data-style="clean"].dm-prx.dm-panel .dm-prx-done>svg{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-prx-f .dm-pill.dm-ghost:hover,:root [data-style="clean"] .dm-prx-f .dm-pill.dm-ghost:hover,:root [data-style="clean"].dm-prx-f .dm-pill.dm-ghost:hover{background:var(--dm-row)}}

